#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    string s;
    cin >> n >> s;
    if (count(s.begin(), s.end(), 'R') % 2 == 0) { cout << n * n << "\n"; return 0; }
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // preorder so every subtree is a contiguous range
    vector<int> parent(n, -1), order, st = {0};
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        order.push_back(v);
        for (int w : g[v]) if (w != parent[v]) { parent[w] = v; st.push_back(w); }
    }
    vector<int> pos(n), sz(n, 1);
    for (int i = 0; i < n; i++) pos[order[i]] = i;
    for (int i = n - 1; i > 0; i--) sz[parent[order[i]]] += sz[order[i]];
    int base = 1;
    while (base < n) base *= 2;
    vector<long long> lazy(2 * base, 0);
    // range chmax on [l, r) without pushing; push everything down at the end
    auto update = [&](int l, int r, long long v) {
        for (l += base, r += base; l < r; l /= 2, r /= 2) {
            if (l & 1) { lazy[l] = max(lazy[l], v); l++; }
            if (r & 1) { r--; lazy[r] = max(lazy[r], v); }
        }
    };
    for (int v = 0; v < n; v++) {
        if (s[v] != 'R') continue;
        // keep v closed: each neighboring component is fully reachable from inside
        update(0, pos[v], n - sz[v]);
        update(pos[v] + sz[v], n, n - sz[v]);
        for (int w : g[v]) if (parent[w] == v) update(pos[w], pos[w] + sz[w], sz[w]);
    }
    for (int i = 1; i < base; i++) {
        lazy[2 * i] = max(lazy[2 * i], lazy[i]);
        lazy[2 * i + 1] = max(lazy[2 * i + 1], lazy[i]);
    }
    long long total = 0;
    for (int i = 0; i < n; i++) total += lazy[base + i];
    cout << total << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c < '0' || c > '9') c = read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return r;
    }

    static String nextWord() throws IOException {
        int c = read();
        while (c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    static int base;
    static long[] lazy;

    // range chmax on [l, r) without pushing; push everything down at the end
    static void update(int l, int r, long v) {
        for (l += base, r += base; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lazy[l] = Math.max(lazy[l], v); l++; }
            if ((r & 1) == 1) { r--; lazy[r] = Math.max(lazy[r], v); }
        }
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String s = nextWord();
        int rs = 0;
        for (int i = 0; i < n; i++) if (s.charAt(i) == 'R') rs++;
        if (rs % 2 == 0) { System.out.println((long) n * n); return; }
        int[] eu = new int[n - 1], ev = new int[n - 1], start = new int[n + 1];
        for (int i = 0; i < n - 1; i++) { eu[i] = nextInt(); ev[i] = nextInt(); start[eu[i] + 1]++; start[ev[i] + 1]++; }
        for (int i = 0; i < n; i++) start[i + 1] += start[i];
        int[] adj = new int[2 * (n - 1)], fill = Arrays.copyOf(start, n);
        for (int i = 0; i < n - 1; i++) { adj[fill[eu[i]]++] = ev[i]; adj[fill[ev[i]]++] = eu[i]; }
        // preorder so every subtree is a contiguous range
        int[] parent = new int[n], order = new int[n], st = new int[n];
        Arrays.fill(parent, -1);
        int top = 0, cnt = 0;
        st[top++] = 0;
        while (top > 0) {
            int v = st[--top];
            order[cnt++] = v;
            for (int e = start[v]; e < start[v + 1]; e++) {
                int w = adj[e];
                if (w != parent[v]) { parent[w] = v; st[top++] = w; }
            }
        }
        int[] pos = new int[n], sz = new int[n];
        Arrays.fill(sz, 1);
        for (int i = 0; i < n; i++) pos[order[i]] = i;
        for (int i = n - 1; i > 0; i--) sz[parent[order[i]]] += sz[order[i]];
        base = 1;
        while (base < n) base *= 2;
        lazy = new long[2 * base];
        for (int v = 0; v < n; v++) {
            if (s.charAt(v) != 'R') continue;
            // keep v closed: each neighboring component is fully reachable from inside
            update(0, pos[v], n - sz[v]);
            update(pos[v] + sz[v], n, n - sz[v]);
            for (int e = start[v]; e < start[v + 1]; e++) {
                int w = adj[e];
                if (parent[w] == v) update(pos[w], pos[w] + sz[w], sz[w]);
            }
        }
        for (int i = 1; i < base; i++) {
            lazy[2 * i] = Math.max(lazy[2 * i], lazy[i]);
            lazy[2 * i + 1] = Math.max(lazy[2 * i + 1], lazy[i]);
        }
        long total = 0;
        for (int i = 0; i < n; i++) total += lazy[base + i];
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n int
	var s string
	fmt.Fscan(in, &n, &s)
	if strings.Count(s, "R")%2 == 0 {
		fmt.Println(n * n)
		return
	}
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	// preorder so every subtree is a contiguous range
	parent := make([]int, n)
	for i := range parent {
		parent[i] = -1
	}
	order := make([]int, 0, n)
	st := []int{0}
	for len(st) > 0 {
		v := st[len(st)-1]
		st = st[:len(st)-1]
		order = append(order, v)
		for _, w := range g[v] {
			if w != parent[v] {
				parent[w] = v
				st = append(st, w)
			}
		}
	}
	pos := make([]int, n)
	sz := make([]int, n)
	for i, v := range order {
		pos[v] = i
		sz[v] = 1
	}
	for i := n - 1; i > 0; i-- {
		sz[parent[order[i]]] += sz[order[i]]
	}
	base := 1
	for base < n {
		base *= 2
	}
	lazy := make([]int, 2*base)
	// range chmax on [l, r) without pushing; push everything down at the end
	update := func(l, r, v int) {
		for l, r = l+base, r+base; l < r; l, r = l/2, r/2 {
			if l&1 == 1 {
				lazy[l] = max(lazy[l], v)
				l++
			}
			if r&1 == 1 {
				r--
				lazy[r] = max(lazy[r], v)
			}
		}
	}
	for v := 0; v < n; v++ {
		if s[v] != 'R' {
			continue
		}
		// keep v closed: each neighboring component is fully reachable from inside
		update(0, pos[v], n-sz[v])
		update(pos[v]+sz[v], n, n-sz[v])
		for _, w := range g[v] {
			if parent[w] == v {
				update(pos[w], pos[w]+sz[w], sz[w])
			}
		}
	}
	for i := 1; i < base; i++ {
		lazy[2*i] = max(lazy[2*i], lazy[i])
		lazy[2*i+1] = max(lazy[2*i+1], lazy[i])
	}
	total := 0
	for i := 0; i < n; i++ {
		total += lazy[base+i]
	}
	fmt.Println(total)
}
